-- Cashback: 15% do preço da venda + código com os 4 primeiros dígitos do CPF
SELECT v.[Preço] * 0.15, LEFT(c.CPF, 4), v.IdVenda
FROM Venda v
INNER JOIN Cliente c ON v.IdCliente = c.IdCliente;
GO